927	  private calcularResumo(
928	    pedidos: any[],
929	    saidas: any[],
930	    valor_inicial: number,
931	    entradas: any[] = [],
932	    pagamentosPorComanda?: Map<number, { valor: number; forma_pagamento: string; taxa_cartao_valor?: number }[]>,
933	  ) {
934	    const entregues = pedidos.filter((p) => this.STATUS_VENDA_FINALIZADA.includes(p.status));
935	    const total_saidas = saidas.reduce((s: number, e: any) => s + (e.valor ?? 0), 0);
936	    const total_entradas = entradas.reduce((s: number, e: any) => s + (e.valor ?? 0), 0);
937	
938	    // orders.total (comanda do salão) guarda só subtotal-desconto+acréscimo — a taxa de
939	    // cartão cobrada do cliente fica em comanda_pagamentos.taxa_cartao_valor. Entra num
940	    // bucket "taxa_cartao" à parte (não somado dentro de Cartão Crédito/Débito) pra
941	    // aparecer explícito na conferência de fechamento, sem esconder dentro da forma.
942	    let total_vendas = 0;
943	    const por_pagamento: Record<string, number> = {};
944	    for (const p of entregues) {
945	      const pagamentosComanda = p.canal === 'presencial' ? pagamentosPorComanda?.get(p.id) : undefined;
946	      if (pagamentosComanda?.length) {
947	        for (const pag of pagamentosComanda) {
948	          const m = pag.forma_pagamento ?? 'outro';
949	          const taxa = pag.taxa_cartao_valor ?? 0;
950	          por_pagamento[m] = (por_pagamento[m] ?? 0) + (pag.valor ?? 0);
951	          if (taxa > 0) por_pagamento['taxa_cartao'] = (por_pagamento['taxa_cartao'] ?? 0) + taxa;
952	          total_vendas += (pag.valor ?? 0) + taxa;
953	        }
954	      } else {
955	        const m = p.payment_method ?? 'outro';
956	        por_pagamento[m] = (por_pagamento[m] ?? 0) + (p.total ?? 0);
957	        total_vendas += p.total ?? 0;
958	      }
959	    }
960	
961	    const vendas_dinheiro = por_pagamento['cash'] ?? 0;
962	    const saidas_especie = saidas
963	      .filter((s: any) => !s.meio || s.meio === 'dinheiro')
964	      .reduce((s: number, e: any) => s + (e.valor ?? 0), 0);
965	    const entradas_especie = entradas
966	      .filter((e: any) => !e.meio || e.meio === 'dinheiro')
967	      .reduce((s: number, e: any) => s + (e.valor ?? 0), 0);
968	    const especie_calculada = valor_inicial + vendas_dinheiro + entradas_especie - saidas_especie;
969	
970	    return {
971	      total_pedidos: pedidos.length,
972	      entregues: entregues.length,
973	      em_andamento: pedidos.filter((p: any) => this.STATUS_ABERTOS.includes(p.status) || this.COMANDA_STATUS_ABERTOS.includes(p.status)).length,
974	      cancelados: pedidos.filter((p: any) => p.status === 'canceled').length,
975	      total_vendas,
976	      total_saidas,
977	      total_entradas,
978	      saldo: valor_inicial + total_vendas + total_entradas - total_saidas,
979	      por_pagamento,
980	      especie_calculada,
981	      saidas_especie,
982	      entradas_especie,
983	    };
984	  }
